package service

import (
	"runtime"
	"strconv"
	"time"
)

const (
	// previewPolicyVersion is the cache-key policy segment for the ordinary
	// gallery preview. It changes whenever the generated bytes change, so old
	// decodes can never be served for a new policy.
	previewPolicyVersion = "v5"
	// previewSelectedPolicyVersion isolates previews read through the selected
	// image representative: an earlier decode could start from a changing
	// original, so those caches are deliberately separate.
	previewSelectedPolicyVersion = "v6"

	// Mobile stills decode the full original through ffmpeg instead of the
	// bounded Go decoder. Keep a hard process cap and a generous timeout; the
	// video pipe retains its existing smaller budget.
	stillPreviewMaxAlloc = 256 << 20
	stillPreviewTimeout  = 60 * time.Second
	videoPreviewTimeout  = 30 * time.Second

	// A single mobile full-original still decode may allocate most of the
	// process budget. Large stills therefore run one at a time.
	mobileLargeStillPixels = 50_000_000
	mobileLargeStillBytes  = 128 << 20
	mobileLargeStillSlots  = 1
)

// PreviewPolicyVersion is the exported cache policy version. API consumers use
// it to skip prefetching when their local cache already matches.
func PreviewPolicyVersion() string { return previewPolicyVersion }

func previewPrefix(version int64, selected bool) string {
	policy := previewPolicyVersion
	if selected {
		policy = previewSelectedPolicyVersion
	}
	return policy + "-" + strconv.FormatInt(version, 10) + "-"
}

// stillDecodeUsesFFmpeg reports whether a built-in still (JPEG/PNG/GIF) should
// be decoded from the full original by ffmpeg. The embedded Android server
// follows the old client pipeline; desktop and NAS keep the bounded Go path.
// The inputs are explicit so the routing decision is testable off-device.
func stillDecodeUsesFFmpeg(android bool, ffmpegPath string) bool {
	return android && ffmpegPath != ""
}

func (s *Service) mobileStillFFmpeg() bool {
	if runtime.GOOS != "android" {
		return false
	}
	return stillDecodeUsesFFmpeg(true, toolPath("QIMENG_FFMPEG", "ffmpeg"))
}

// mobileLargeStill marks originals that need the full-decode semaphore. Pixel
// count is checked in int64 to avoid overflow on cataloged dimensions.
func mobileLargeStill(width, height int, size int64) bool {
	if width > 0 && height > 0 && int64(width)*int64(height) > mobileLargeStillPixels {
		return true
	}
	return size > mobileLargeStillBytes
}
